class Account {
    var balance: Int
    init(balance: Int) { self.balance = balance }
    deinit { print("Account closed") }
}

func update(_ account: Account) {
    account.balance += 50
}

var acc: Account? = Account(balance: 100)
update(acc!)
print("Balance: \(acc?.balance ?? 0)")
acc = nil

