class Logger {
    let tag: String
    init(tag: String) {
        self.tag = tag
        print("Start: \(tag)")
    }
    deinit {
        print("End: \(tag)")
    }
}

do {
    let logger = Logger(tag: "Network")
    print("Working with \(logger.tag)")
}
print("Done")

class Session {
    let name: String
    init(name: String) {
        self.name = name
    }
    deinit {
        print("Session \(name) expired")
    }
}

func runSession() {
    var s1: Session? = Session(name: "Guest")
    var s2: Session? = s1
    print("Session active: \(s2?.name ?? "")")
    s1 = nil
    print("s1 cleared")
    s2 = nil
    print("s2 cleared")
}

runSession()

class FileHandler {
    let path: String
    init(path: String) {
        self.path = path
        print("Opened \(path)")
    }
    deinit {
        print("Closed \(path)")
    }
}

do {
    let file = FileHandler(path: "/tmp/data.txt")
    print("Reading \(file.path)")
}
print("Finished file operation")
